namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class GKChesterton
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Impartiality is a pompous name for indifference, which is an elegant name for ignorance.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There is a certain poetic value, and that a genuine one, in this sense of having missed the full meaning of things. There is beauty, not only in wisdom, but in this dazed and dramatic ignorance.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The only thing that has kept the race of men from the mad extremes of the convent and the pirate-galley, the night-club and the lethal chamber, has been mysticism — the belief that logic is misleading, and that things are not what they seem.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Reason is always a kind of brute force; those who appeal to the head rather than the heart, however pallid and polite, are necessarily men of violence. We speak of 'touching' a man's heart, but we can do nothing to his head but hit it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The centre of every man's existence is a dream.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The simplification of anything is always sensational.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "He is only a very shallow critic who cannot see an eternal rebel in the heart of the Conservative.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There is only one thing that it requires real courage to say, and that is a truism.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Briefly, you can only find truth with logic if you have already found truth without it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Without education, we are in a horrible and deadly danger of taking educated people seriously.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Ritual is a need of the human soul — nay, it is rather a need of the human body, like exercise.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The riddle of life is simply this: For some mad reason in this mad world of ours, the things which men differ about most are exactly the things about which they must be got to agree. Men can agree on the fact that the earth goes round the sun. But then it does not matter a dump whether the earth goes around the sun or the Pleiades. But men cannot agree about morals: sex, property, individual rights, fixity and contracts, patriotism, suicide, public habits of health – these are exactly the things that men tend to fight about. And these are exactly the things that must be settled somehow on strict principles. Study each of them, and you will find each of them works back certainly to a philosophy, probably to a religion.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The riddles of God are more satisfying than the solutions of man.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Men do not differ much about what things they will call evils; they differ enormously about what evils they will call excusable.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The Bible tells us to love our neighbors, and also to love our enemies; probably because they are generally the same people.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The whole difference between construction and creation is exactly this: that a thing constructed can only be loved after it is constructed; but a thing created is loved before it exists, as the mother can love the unborn child.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Either criticism is no good at all (a very defensible position) or else criticism means saying about an author the very things that would have made him jump out of his boots.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Among the rich you will never find a really generous man even by accident. They may give their money away, but they will never give themselves away; they are egotistic, secretive, dry as old bones. To be smart enough to get all that money you must be dull enough to want it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "I object to a quarrel because it always interrupts an argument.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "To have a right to do a thing is not at all the same as to be right in doing it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "All government is an ugly necessity.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "I would maintain that thanks are the highest form of thought; and that gratitude is happiness doubled by wonder.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "When a politician is in opposition he is an expert on the means to some end; and when he is in office he is an expert on the obstacles to it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "A mystic is a man who separates heaven and earth even if he enjoys them both.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "They seem to forget that if the Crusaders nearly conquered Palestine, it was but a return upon the Moslems who had nearly conquered Europe.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "When men have a real explanation they explain it, eagerly and copiously and in common speech.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "When they have no explanation to offer, they give short dignified replies, disdainful of the ignorance of the multitude.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "It is terrible to contemplate how few politicians are hanged.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There are two ways of dealing with nonsense in this world. One way is to put nonsense in the right place; as when people put nonsense into nursery rhymes. The other is to put nonsense in the wrong place; as when they put it into educational addresses, psychological criticisms, and complaints against nursery rhymes or other normal amusements of mankind.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "For children are innocent and love justice; while most of us are wicked and naturally prefer mercy.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "I do not believe in a fate that falls on men however they act; but I believe in a fate that falls on them unless they act.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "I believe what really happens in history is this: the old man is always wrong; and the young people are always wrong about what is wrong with him. The practical form it takes is this: that, while the old man may stand by some stupid custom, the young man always attacks it with some theory that turns out to be equally stupid.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Atheism is, I suppose, the supreme example of a simple faith.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Irreverence is a very servile parasite of reverence; and has starved with its starving lord.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "If there were not God, there would be no atheists.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The whole modern world has divided itself into Conservatives and Progressives. The business of Progressives is to go on making mistakes. The business of Conservatives is to prevent mistakes from being corrected.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Neither reason nor faith will ever die; for men would die if deprived of either. The wildest mystic uses his reason at some stage; if it be only by reasoning against reason. The most incisive sceptic has dogmas of his own; though when he is a very incisive sceptic, he has often forgotten what they are. Faith and reason are in this sense co-eternal; but as the words are popularly used, as loose labels for particular periods, the one is now almost as remote as the other. What was called the Age of Reason has vanished as completely as what are called the Ages of Faith.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "We shall soon be in a world in which a man may be howled down for saying that two and two make four, in which furious party cries will be raised against anybody who says that cows have horns, in which people will persecute the heresy of calling a triangle a three-sided figure, and hang a man for maddening a mob with the news that grass is green.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "These are the days when the Christian is expected to praise every creed except his own.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The full potentialities of human fury cannot be reached until a friend of both parties tactfully intervenes.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Fallacies do not cease to be fallacies because they become fashions.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There is something to be said for every error; but, whatever may be said for it, the most important thing to be said about it is that it is erroneous.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The modern world seems to have no notion of preserving different things side by side, of allowing its proper and proportionate place to each, of saving the whole varied heritage of culture. It has no notion except that of simplifying something by destroying nearly everything.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "What embitters the world is not excess of criticism, but absence of self-criticism.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "We must not hate humanity, or despise humanity, or refuse to help humanity; but we must not trust humanity; in the sense of trusting a trend in human nature which cannot turn back to bad things.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Half the trouble about the modern man is that he is educated to understand foreign languages and misunderstand foreigners.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "A stiff apology is a second insult.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The cause which is blocking all progress today is the subtle scepticism which whispers in a million ears that things are not good enough to be worth improving. If the world is good we are revolutionaries, if the world is evil we must be conservatives.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "In our time the blasphemies are threadbare. Pessimism is now patently, as it always was essentially, more commonplace than piety.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There runs a strange law through the length of human history — that men are continually tending to undervalue their environment, to undervalue their happiness, to undervalue themselves. The great sin of mankind, the sin typified by the fall of Adam, is the tendency, not towards pride, but towards this weird and horrible humility.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "It is only our eyes that have changed.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The person who is really in revolt is the optimist, who generally lives and dies in a desperate and suicidal effort to persuade all the other people how good they are.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Every one of the great revolutionists, from Isaiah to Shelley, have been optimists. They have been indignant, not about the badness of existence, but about the slowness of men in realizing its goodness.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Ivory may not be so white as snow, but the whole Arctic continent does not make ivory black.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "I have investigated the dust-heaps of humanity, and found a treasure in all of them. I have found that humanity is not incidentally engaged, but eternally and systematically engaged, in throwing gold into the gutter and diamonds into the sea.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Humility is the luxurious art of reducing ourselves to a point, not to a small thing or a large one, but to a thing with no size at all, so that to it all the cosmic things are what they really are — of immeasurable stature.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "We all do warmly respect humility — in other people.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "It is always the secure who are humble.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There is a road from the eye to the heart that does not go through the intellect.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The one stream of poetry which is continually flowing is slang.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "All slang is metaphor, and all metaphor is poetry.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The most unfathomable schools and sages have never attained to the gravity which dwells in the eyes of a baby of three months old. It is the gravity of astonishment at the universe, and astonishment at the universe is not mysticism, but a transcendent common-sense.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "If we could destroy custom at a blow and see the stars as a child sees them, we should need no other apocalypse.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The truth is that it is our attitude towards children that is right, and our attitude towards grown-up people that is wrong.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "We should probably come considerably nearer to the true conception of things if we treated all grown-up persons, of all titles and types, with precisely that dark affection and dazed respect with which we treat the infantile limitations.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "When we look upon lives so human and yet so small, we feel as if we ourselves were enlarged to an embarrassing bigness of stature. We feel the same kind of obligation to these creatures that a deity might feel if he had created something that he could not understand.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The humorous look of children is perhaps the most endearing of all the bonds that hold the Cosmos together.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The human race, to which so many of my readers belong, has been playing at children's games from the beginning, and will probably do it till the end, which is a nuisance for the few people who grow up.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "They then go and do something else.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "For human beings, being children, have the childish wilfulness and the childish secrecy. And they never have from the beginning of the world done what the wise men have seen to be inevitable.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "All revolutions are doctrinal — such as the French one, or the one that introduced Christianity.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Can you tell me, in a world that is flagrant with the failures of civilisation, what there is particularly immortal about yours?", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Don't you believe people when they tell you that people sought for a sign, and believed in miracles because they were ignorant. They did it because they were wise, filthily, vilely wise—too wise to eat or sleep or put on their boots with patience.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Lord! what a strange world in which a man cannot remain unique even by taking the trouble to go mad!", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Bosh, he said, On what else is the whole world run but immediate impressions? What is more practical? My friend, the philosophy of this world may be founded on facts, but its business is run on spiritual impressions and atmospheres.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Truth must of necessity be stranger than fiction ... for fiction is the creation of the human mind, and therefore is congenial to it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Men always talk about the most important things to total strangers. It is because in the total stranger we perceive man himself; the image of God is not disguised by resemblances to an uncle or doubts of the wisdom of a moustache.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Much of our modern difficulty, in religion and other things, arises merely from this: that we confuse the word \"indefinable\" with the word \"vague.\"", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The thing that cannot be defined is the first thing; the primary fact.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The indefinable is the indisputable. The man next door is indefinable, because he is too actual to be defined. And there are some to whom spiritual things have the same fierce and practical proximity; some to whom God is too actual to be defined.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Whatever the word \"great\" means, Dickens was what it means.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "One of the actual and certain consequences of the idea that all men are equal is immediately to produce very great men.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "There is a great man who makes every man feel small. But the real great man is the man who makes every man feel great.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "For religion all men are equal, as all pennies are equal, because the only value in any of them is that they bear the image of the King.... It has often been said, very truly, that religion is the thing that makes the ordinary man feel extraordinary; it is an equally important truth that religion is the thing that makes the extraordinary man feel ordinary.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "And when anybody goes about on his hands and knees looking for a great man to worship, he is making sure that one man at any rate shall not be great.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "No man encouraged his characters so much as Dickens. \"I am an affectionate father,\" he says, \"to every child of my fancy.\" He was not only an affectionate father, he was an overindulgent father. The children of his fancy are spoilt children. They shake the house like heavy and shouting schoolboys; they smash the story to pieces like so much furniture.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The emancipated poets of to-day have written it over the gates of this world.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Dickens was always a little too irritable because he was a little too happy.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Sorrow and pessimism are indeed, in a sense, opposite things, since sorrow is founded on the value of something, and pessimism upon the value of nothing.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "These higher optimists, of whom Dickens was one, do not approve of the universe; they do not even admire the universe; they fall in love with it. They embrace life too close to criticize or even to see it.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "[Dickens] was the character whom anybody can hurt and nobody can kill.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "He turned people into mortal enemies whom he might have turned very easily into immortal jokes.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Fiction means the common things as seen by the uncommon people. Fairy tales mean the uncommon things as seen by the common people.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "Cockney artists profess to find the bourgeoisie dull; as if artists had any business to find anything dull.", Author = "G. K. Chesterton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/G._K._Chesterton", Text = "The public likes a certain kind of literature and likes that kind of literature even when it is bad better than another kind of literature even when it is good.", Author = "G. K. Chesterton" },
        };
    }
}